'use strict';
const $ = id => document.getElementById(id);
const API = 'https://earth-search.aws.element84.com/v1/search';
const today = new Date().toISOString().slice(0, 10);
const initialDate = new Date(Date.now() - 7 * 86400000).toISOString().slice(0, 10);
const state = {lat:32.916,lon:75.141,name:'Udhampur, India',placeText:'Udhampur, India',scenes:[],date:initialDate,target:0,request:0,geoRequest:0,selected:null,query:null,dirty:false};
let map, marker, nasa, streets, footprint, currentController;
$('date').value = initialDate; $('date').max = today;
function text(tag, value, cls) { const e = document.createElement(tag); e.textContent = value; if(cls)e.className=cls;return e; }
function safeURL(href) { try {const u = new URL(href);return u.protocol === 'https:' ? u.href : null;}catch{return null;} }
function dateLabel(value) {return new Date(value).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'});}
function captureTime(value) {return new Date(value).toISOString().slice(11,19)+' UTC';}
function platform(f) {return String(f.properties.platform || 'Satellite not reported').replace(/-/g,' ').replace(/\b\w/g,c=>c.toUpperCase());}
function cloud(f) {const v=f.properties['eo:cloud_cover'];return typeof v==='number'&&Number.isFinite(v)?v:null;}
function cloudLabel(f) {const c=cloud(f);return c===null?'Clouds unknown':c.toFixed(1)+'% cloud';}
function resolution(f) {return f.collection==='sentinel-2-l2a'?'10 m RGB':'30 m RGB';}
function previewURL(f) {const assets=f.assets||{};for(const [key,a] of Object.entries(assets)){if(key==='thumbnail'||key==='rendered_preview'||(a.roles||[]).includes('thumbnail')){const u=safeURL(a.href);if(u)return u;}}return null;}
function assetURL(f,key) {return safeURL(f.assets?.[key]?.href);}
async function fetchJSON(url,signal) {const r=await fetch(url,{signal,headers:{Accept:'application/geo+json, application/json'}});if(!r.ok)throw Error(r.status===429?'The imagery service is busy. Please wait a minute and retry.':`The service could not complete this request (HTTP ${r.status}). Please retry.`);return r.json();}
function warnMap(message) {$('map-warning').textContent=message;$('map-warning').hidden=!message;}
function updateMapLayer() {
  if(!map)return;
  if(nasa)map.removeLayer(nasa);
  warnMap('');
  const street=$('map-layer').value==='streets';
  $('map-source').textContent=street?'OpenStreetMap · Reference map':'Terra / MODIS · Daily overview';
  $('map-date').textContent=street?'Reference only · Not capture-date imagery':`${dateLabel(state.date)} · Daily mosaic · Not a selected scene`;
  if(street){streets.setOpacity(1);return;}
  streets.setOpacity(0);
  nasa=L.tileLayer(`https://gibs.earthdata.nasa.gov/wmts/epsg3857/best/MODIS_Terra_CorrectedReflectance_TrueColor/default/${state.date}/GoogleMapsCompatible_Level9/{z}/{y}/{x}.jpg`,{maxNativeZoom:9,maxZoom:17,noWrap:true,attribution:'Imagery: <a href="https://www.earthdata.nasa.gov/">NASA GIBS</a>',bounds:[[-85,-180],[85,180]]}).addTo(map);
  nasa.on('tileerror',()=>warnMap('NASA overview tiles could not load. Try Street map; scene search is separate.'));
  if(new Date(state.date)<new Date('2000-02-24'))warnMap('This date predates Terra/MODIS imagery. Use Street map to locate the historical scenes.');
}
function initMap() {
  if(!window.L){$('map').append(text('div','The interactive map could not load. You can still search imagery by place or coordinates.','map-unavailable'));$('map-date').textContent='Map service unavailable';$('map-layer').disabled=true;return;}
  map=L.map('map',{zoomControl:false,worldCopyJump:true,minZoom:2,maxZoom:17}).setView([state.lat,state.lon],7);
  L.control.zoom({position:'bottomright'}).addTo(map);
  streets=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);
  streets.on('tileerror',()=>{if($('map-layer').value==='streets')warnMap('Street-map tiles could not load. You can still search by place or coordinates.');});
  marker=L.marker([state.lat,state.lon],{icon:L.divIcon({className:'',html:'<div class="pin-dot"></div>',iconSize:[16,16],iconAnchor:[8,8]}),keyboard:false}).addTo(map);
  map.on('click',e=>{const lon=((e.latlng.lng+180)%360+360)%360-180;const lat=Math.max(-90,Math.min(90,e.latlng.lat));setPlace(lat,lon,`${lat.toFixed(4)}, ${lon.toFixed(4)}`,false);});
  updateMapLayer();
}
function clearResults(message) {state.scenes=[];state.selected=null;$('count').textContent='—';$('export').disabled=true;$('scene-list').replaceChildren(empty('Ready for another perspective',message));if(footprint&&map){map.removeLayer(footprint);footprint=null;}}
function invalidate() {state.request++;currentController?.abort();$('search-button').disabled=false;$('search-button').replaceChildren(text('span','Find satellite images'),text('span','↗'));clearResults('Your search changed. Select Find satellite images to update the results.');$('result-summary').textContent='Search settings changed.';}
function setPlace(lat,lon,name,fly=true) {state.geoRequest++;$('find-place').disabled=false;state.lat=lat;state.lon=lon;state.name=name;state.placeText=name;state.dirty=false;$('place').value=name;$('place-results').replaceChildren();$('location-title').textContent=name;$('coordinates').textContent=`${Math.abs(lat).toFixed(4)}° ${lat>=0?'N':'S'}, ${Math.abs(lon).toFixed(4)}° ${lon>=0?'E':'W'}`;if(map){marker.setLatLng([lat,lon]);if(fly)map.setView([lat,lon],Math.min(10,Math.max(7,map.getZoom())));}invalidate();$('search-notice').textContent='Location selected. Find images to update the archive results.';}
function parseCoords(q) {const m=q.trim().match(/^(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)$/);if(!m)return null;const lat=Number(m[1]),lon=Number(m[2]);if(lat < -90||lat>90||lon < -180||lon>180)throw Error('Use latitude from −90 to 90 and longitude from −180 to 180.');return [lat,lon];}
async function findPlace() {const q=$('place').value.trim();if(!q){$('search-notice').textContent='Enter a place name or latitude, longitude.';return false;}const request=++state.geoRequest;try {const coords=parseCoords(q);if(coords){setPlace(...coords,q);return true;}$('find-place').disabled=true;$('search-notice').textContent='Finding places…';const url=window.EARTH_WINDOW_PYTHON?'/api/geocode?'+new URLSearchParams({q}):'https://geocoding-api.open-meteo.com/v1/search?'+new URLSearchParams({name:q,count:5,language:'en',format:'json'});const raw=await fetchJSON(url,AbortSignal.timeout(20000));const results=window.EARTH_WINDOW_PYTHON?raw:(raw.results||[]).map(p=>({lat:p.latitude,lon:p.longitude,display_name:[p.name,p.admin1,p.country].filter(Boolean).join(', ')}));if(request!==state.geoRequest)return false;$('place-results').replaceChildren();if(!Array.isArray(results)||!results.length)throw Error('No matching place found. Try another name or enter latitude, longitude.');if(results.length===1){setPlace(Number(results[0].lat),Number(results[0].lon),results[0].display_name);return true;}for(const place of results){const b=text('button',place.display_name);b.type='button';b.onclick=()=>setPlace(Number(place.lat),Number(place.lon),place.display_name);$('place-results').append(b);}$('search-notice').textContent='Choose the matching location above, then find images.';return false;}catch(e){if(request===state.geoRequest)$('search-notice').textContent=e.name==='TimeoutError'?'Place lookup timed out. Try coordinates or click the map.':e.message;return false;}finally{if(request===state.geoRequest)$('find-place').disabled=false;}}
function searchParams() {const date=$('date').value,time=$('time').value;if(!date||!time)throw Error('Choose a date and UTC time.');const target=new Date(`${date}T${time}:00Z`);if(!Number.isFinite(+target))throw Error('Choose a valid date and UTC time.');if(date>today)throw Error('Future imagery is not available. Choose today or an earlier date.');if(date<'1982-01-01')throw Error('Choose a date from 1982 onward.');const days=Number($('window').value);const start=new Date(`${date}T00:00:00Z`);start.setUTCDate(start.getUTCDate()-days);const end=new Date(`${date}T23:59:59.999Z`);end.setUTCDate(end.getUTCDate()+days);return {date,time,days,target:+target,start:start.toISOString(),end:new Date(Math.min(+end,Date.now())).toISOString(),collection:$('collection').value,cloud:Number($('cloud').value),lat:state.lat,lon:state.lon};}
async function fetchScenes(q,signal) {if(window.EARTH_WINDOW_PYTHON)return fetchJSON('/api/search?'+new URLSearchParams({lat:q.lat,lon:q.lon,date:q.date,time:q.time,window:q.days,collection:q.collection,cloud:q.cloud}),signal);const params=new URLSearchParams({collections:q.collection,intersects:JSON.stringify({type:'Point',coordinates:[q.lon,q.lat]}),datetime:`${q.start}/${q.end}`,query:JSON.stringify({'eo:cloud_cover':{lte:q.cloud}}),limit:100});let url=API+'?'+params;let features=[],truncated=false;for(let page=0;page<5;page++){const data=await fetchJSON(url,signal);if(!Array.isArray(data.features))throw Error('The imagery service returned an unexpected response. Please retry.');features.push(...data.features);const next=data.links?.find(l=>l.rel==='next');if(!next)break;const nextURL=safeURL(next.href);if(!nextURL||new URL(nextURL).origin!==new URL(API).origin||(next.method&&next.method!=='GET')){truncated=true;break;}url=nextURL;if(page===4)truncated=true;}return {features,truncated};}
function empty(title,message) {const e=text('div','','empty-state');e.append(text('span','◎'),text('h3',title),text('p',message));return e;}
async function search(event) {event?.preventDefault();if(state.dirty||$('place').value.trim()!==state.placeText){if(!await findPlace())return;}let q;try{q=searchParams();}catch(e){$('search-notice').textContent=e.message;return;}const request=++state.request;currentController?.abort();currentController=new AbortController();const controller=currentController;const timeout=setTimeout(()=>controller.abort(),60000);const signal=controller.signal;state.target=q.target;state.date=q.date;state.query={...q,name:state.name};clearResults('');updateMapLayer();$('search-button').disabled=true;$('search-button').textContent='Searching the archive…';$('search-notice').textContent='';$('result-summary').textContent='Checking satellite footprints and capture times…';$('scene-list').replaceChildren(...Array.from({length:3},()=>text('div','','skeleton')));try{const data=await fetchScenes(q,signal);if(request!==state.request)return;state.scenes=Array.from(new Map(data.features.filter(f=>f.properties?.datetime&&Number.isFinite(Date.parse(f.properties.datetime))).map(f=>[f.id,f])).values());$('count').textContent=state.scenes.length;$('export').disabled=!state.scenes.length;const interval=`${dateLabel(q.start)} – ${dateLabel(q.end)}`;$('result-summary').textContent=`${state.scenes.length} scene${state.scenes.length===1?'':'s'} covering your selected point · ${interval}${data.truncated?' · Partial results: narrow the date window to see all matches.':''}`;renderScenes();if(!state.scenes.length)$('search-notice').textContent='Try a wider time window, a higher cloud limit, or another satellite archive.';}catch(e){if(request!==state.request)return;clearResults('The live imagery service could not be reached. Check your connection and try again.');$('result-summary').textContent='Search unavailable — no sample images are substituted.';$('search-notice').textContent=e.name==='AbortError'?'The search timed out. Please try again.':e.message;}finally{clearTimeout(timeout);if(request===state.request){$('search-button').disabled=false;$('search-button').replaceChildren(text('span','Find satellite images'),text('span','↗'));}}}
function orderedScenes() {return [...state.scenes].sort((a,b)=>{if($('sort').value==='clear')return (cloud(a)??101)-(cloud(b)??101);if($('sort').value==='newest')return Date.parse(b.properties.datetime)-Date.parse(a.properties.datetime);return Math.abs(Date.parse(a.properties.datetime)-state.target)-Math.abs(Date.parse(b.properties.datetime)-state.target);});}
function imagePreview(f,detail=false) {const wrap=text('div','','thumb-wrap');const url=previewURL(f);const fallback=()=>{wrap.replaceChildren(text('div','Preview unavailable · Open source assets for imagery','missing-thumb'));};if(url){const img=document.createElement('img');img.src=url;img.alt=`Full-scene preview from ${platform(f)}, ${dateLabel(f.properties.datetime)}`;img.loading='lazy';img.referrerPolicy='no-referrer';img.onerror=fallback;if(detail){img.className='detail-image';wrap.style.height='auto';}wrap.append(img);}else fallback();if(!detail)wrap.append(text('span',platform(f),'thumb-label'));return wrap;}
function renderScenes() {$('scene-list').replaceChildren();if(!state.scenes.length){$('scene-list').append(empty('No scenes match this search','Satellites capture on particular passes. Widen the date window or allow more cloud cover, then search again.'));return;}for(const f of orderedScenes()){const card=text('article','','scene-card'+(state.selected===f.id?' selected':''));const button=text('button','','scene-open');button.type='button';button.setAttribute('aria-label',`View ${platform(f)} image from ${f.properties.datetime}, ${cloudLabel(f)}`);button.onclick=()=>openScene(f);button.append(imagePreview(f));const body=text('div','','scene-body');body.append(text('h3',dateLabel(f.properties.datetime)));const meta=text('div','','scene-meta');meta.append(text('span',captureTime(f.properties.datetime)),text('span',cloudLabel(f),'cloud-pill'));const bottom=text('div','','scene-bottom');bottom.append(text('span',resolution(f)+' · Full scene'),text('span','Inspect ↗'));body.append(meta,bottom);button.append(body);card.append(button);$('scene-list').append(card);}}
function openScene(f) {state.selected=f.id;renderScenes();if(map&&f.geometry){if(footprint)map.removeLayer(footprint);footprint=L.geoJSON(f.geometry,{style:{color:'#b8f56b',weight:2,fillOpacity:.06}}).addTo(map);}$('scene-details').replaceChildren(imagePreview(f,true));const content=text('div','','detail-content');content.append(text('span','SATELLITE SCENE','eyebrow'),text('h2',platform(f)+' · '+dateLabel(f.properties.datetime)));const dl=text('dl','','detail-grid');const diffHours=(Date.parse(f.properties.datetime)-state.target)/3600000;const entries=[['Captured (UTC)',captureTime(f.properties.datetime)],['Offset from chosen time',`${Math.abs(diffHours).toFixed(1)} hours ${diffHours<0?'before':'after'}`],['Scene cloud cover',cloudLabel(f)],['RGB pixel size',resolution(f)],['Data provider',f.collection==='sentinel-2-l2a'?'Copernicus / ESA':'USGS / NASA'],['Collection',f.collection],['Scene ID',f.id]];for(const [k,v] of entries){const div=text('div','');div.append(text('dt',k),text('dd',v));dl.append(div);}content.append(dl,text('p','This preview shows the full satellite tile. Your selected point lies within its footprint; the preview is not a close-up or a georeferenced overlay. The map remains the labelled NASA overview or street map.','detail-note'));const links=text('div','','detail-links');let visual=assetURL(f,'visual')||assetURL(f,'red');for(const [label,url] of [['Open image preview ↗',previewURL(f)],[assetURL(f,'visual')?'Open RGB GeoTIFF ↗':'Open red-band GeoTIFF ↗',visual],['View source metadata ↗',safeURL(f.links?.find(l=>l.rel==='self')?.href)]]){if(url){const a=text('a',label);a.href=url;a.target='_blank';a.rel='noopener noreferrer';links.append(a);}}content.append(links,text('p','GeoTIFFs can be large. Some source assets may require provider access. Use QGIS or other geospatial software to view full-resolution raster files.','detail-note'));$('scene-details').append(content);$('scene-dialog').showModal();}
$('find-place').onclick=findPlace;
$('place').addEventListener('input',()=>{state.geoRequest++;$('find-place').disabled=false;state.dirty=true;invalidate();$('place-results').replaceChildren();});
$('place').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();findPlace();}});
$('recenter').onclick=()=>map?.setView([state.lat,state.lon],8);
$('map-layer').onchange=updateMapLayer;
$('search-form').onsubmit=search;
for(const id of ['date','time','window','collection','cloud'])$(id).addEventListener('change',invalidate);
$('cloud').addEventListener('input',()=>{$('cloud-value').textContent=$('cloud').value+'%';});
$('sort').onchange=renderScenes;
$('about-open').onclick=()=>$('about-dialog').showModal();
for(const dialog of document.querySelectorAll('dialog')){dialog.querySelector('.close-dialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});}
$('export').onclick=()=>{const payload={type:'FeatureCollection',search:state.query,retrieved_at:new Date().toISOString(),source:API,features:orderedScenes()};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/geo+json'}));const a=document.createElement('a');a.href=url;a.download=`earth-window-${state.query.date}.geojson`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
initMap();
